class Notify{static post(i,n,t){if("Notification"in globalThis&&this.permission()){let o=new Notification(i,{body:n,icon:t});o.onclose=function(){return!1},o.onshow=function(){return!1},o.onclick=function(){return!1}}}static permission(){let i=!1;return Notification.requestPermission().then(function(n){i="granted"==n}),i}}